import { Component, HostListener, OnDestroy, OnInit } from '@angular/core';
import { of, Subject } from 'rxjs';
import {
  catchError,
  debounceTime,
  distinctUntilChanged,
  filter,
  map,
  switchMap,
  takeUntil
} from 'rxjs/operators';
import { VehicleService } from '../services/vehicle.service';
import { Vehicle, VehicleData } from '../models/vehicle.model';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent implements OnInit, OnDestroy {
  // Passo 8: opções do dropdown, carregadas do back-end
  vehicles: Vehicle[] = [];
  selectedVehicle: Vehicle | null = null;
  dropdownAberto = false;

  // Passo 11: busca por código do veículo (VIN)
  vin = '';
  vehicleData: VehicleData | null = null;
  erroVin = '';
  buscando = false;

  // Tamanho dos códigos VIN cadastrados na API (ex.: 2FRHDUYS2Y63NHD22454 tem 20 caracteres).
  // Usar 17 (padrão VIN real) disparava buscas para códigos incompletos enquanto o
  // usuário ainda digitava, mostrando "não encontrado" antes da hora.
  private readonly vinMinLength = 20;

  // Passo 11: códigos VIN cadastrados na API, exibidos para seleção rápida
  vinOptions: string[] = [
    '2FRHDUYS2Y63NHD22454',
    '2RFAASDY54E4HDU34874',
    '2FRHDUYS2Y63NHD22455',
    '2RFAASDY54E4HDU34875',
    '2FRHDUYS2Y63NHD22654',
    '2FRHDUYS2Y63NHD22854'
  ];

  private vin$ = new Subject<string>();
  private destroy$ = new Subject<void>();

  constructor(private vehicleService: VehicleService) {}

  /** Fecha o dropdown ao clicar em qualquer lugar fora dele. */
  @HostListener('document:click')
  fecharDropdown(): void {
    this.dropdownAberto = false;
  }

  ngOnInit(): void {
    // Passo 8: busca das opções de preenchimento no back-end (o service usa "pluck"
    // para extrair a propriedade "vehicles" da resposta).
    this.vehicleService
      .getVehicles()
      .pipe(
        // Normaliza o nome do modelo para exibição no dropdown
        map((vehicles) =>
          vehicles.map((v) => ({ ...v, vehicle: v.vehicle.trim() }))
        ),
        takeUntil(this.destroy$)
      )
      .subscribe((vehicles) => {
        this.vehicles = vehicles;
        if (vehicles.length) {
          this.selectVehicle(vehicles[0]);
        }
      });

    // Passo 11: busca reativa por VIN.
    // debounceTime  -> espera o usuário parar de digitar
    // map           -> normaliza o texto (sem espaços, maiúsculo)
    // distinctUntilChanged -> ignora o mesmo código digitado de novo
    // filter        -> só busca quando o código tem tamanho plausível
    // switchMap     -> cancela a requisição anterior ao digitar um novo código
    this.vin$
      .pipe(
        debounceTime(400),
        map((codigo) => codigo.trim().toUpperCase()),
        distinctUntilChanged(),
        filter((codigo) => codigo.length >= this.vinMinLength),
        switchMap((codigo) => {
          this.buscando = true;
          this.erroVin = '';
          return this.vehicleService.getVehicleData(codigo).pipe(
            catchError((err) => {
              this.erroVin = err?.error?.message || 'Código VIN não encontrado.';
              return of(null);
            })
          );
        }),
        takeUntil(this.destroy$)
      )
      .subscribe((data) => {
        this.buscando = false;
        this.vehicleData = data;
      });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /** Abre/fecha a lista de modelos do primeiro cartão. */
  toggleDropdown(event: Event): void {
    event.stopPropagation();
    this.dropdownAberto = !this.dropdownAberto;
  }

  /** Passo 9 e 10: ao selecionar o modelo, cartões e imagem são atualizados. */
  selectVehicle(vehicle: Vehicle): void {
    this.selectedVehicle = vehicle;
    this.dropdownAberto = false;
  }

  get totalVendas(): number {
    return this.selectedVehicle?.volumetotal ?? 0;
  }

  get conectados(): number {
    return this.selectedVehicle?.connected ?? 0;
  }

  get softwareAtualizado(): number {
    return this.selectedVehicle?.softwareUpdates ?? 0;
  }

  /** Cada tecla digitada alimenta o fluxo reativo do VIN. */
  onVinChange(codigo: string): void {
    this.vehicleData = null;
    this.erroVin = '';
    this.vin$.next(codigo);
  }

  /** Ao clicar em um dos códigos cadastrados, preenche o campo e busca na hora. */
  onVinSelecionado(codigo: string): void {
    this.vin = codigo;
    this.buscarVeiculo();
  }

  /** Busca imediata (botão da lupa ou tecla Enter), sem esperar o debounce. */
  buscarVeiculo(): void {
    const codigo = this.vin.trim().toUpperCase();

    this.erroVin = '';
    this.vehicleData = null;

    if (!codigo) {
      this.erroVin = 'Informe o código do veículo.';
      return;
    }

    this.buscando = true;
    this.vehicleService
      .getVehicleData(codigo)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.buscando = false;
          this.vehicleData = data;
        },
        error: (err) => {
          this.buscando = false;
          this.erroVin = err?.error?.message || 'Código VIN não encontrado.';
        }
      });
  }
}
<!-- Figura 3 - Protótipo das páginas de Dashboards -->
<div class="dashboard-page">

  <!-- Barra superior -->
  <nav class="topbar">
    <a routerLink="/home" class="topbar-link">
      <img src="assets/img/icon-home-white.png" alt="" class="topbar-icon" />
      Home
    </a>
    <span class="topbar-title">Dashboard FORD</span>
    <span class="topbar-spacer"></span>
  </nav>

  <div class="container-fluid px-4 pb-4 pt-3">

    <div class="row g-3 align-items-stretch">

      <!-- Passo 8: cartão com seleção do modelo do veículo -->
      <div class="col-6 col-lg-3">
        <div class="card card-ford h-100">
          <span class="card-label">Veículo</span>

          <!-- Dropdown customizado com visual de <select> -->
          <div class="select-ford" (click)="$event.stopPropagation()">
            <button
              type="button"
              class="btn select-ford-toggle"
              [class.aberto]="dropdownAberto"
              (click)="toggleDropdown($event)"
              [attr.aria-expanded]="dropdownAberto"
            >
              <span class="select-ford-valor">
                {{ selectedVehicle ? selectedVehicle.vehicle : 'Selecione' }}
              </span>
              <svg class="select-ford-seta" width="10" height="10" viewBox="0 0 16 16" aria-hidden="true">
                <path d="M3 5.5l5 5 5-5H3z" fill="currentColor" />
              </svg>
            </button>

            <ul class="select-ford-lista list-unstyled" *ngIf="dropdownAberto">
              <li
                *ngFor="let v of vehicles"
                class="select-ford-opcao"
                [class.selecionada]="selectedVehicle?.id === v.id"
                (click)="selectVehicle(v)"
              >
                {{ v.vehicle }}
              </li>
              <li class="select-ford-vazio" *ngIf="!vehicles.length">
                Nenhum modelo disponível.
              </li>
            </ul>
          </div>
        </div>
      </div>

      <!-- Passo 9: três cartões atualizados conforme o modelo selecionado -->
      <div class="col-6 col-lg-3">
        <div class="card card-ford h-100">
          <span class="card-label">Total de Vendas</span>
          <span class="card-valor">{{ totalVendas }}</span>
          <span class="card-unidade">Und</span>
        </div>
      </div>

      <div class="col-6 col-lg-3">
        <div class="card card-ford h-100">
          <span class="card-label">Conectados</span>
          <span class="card-valor">{{ conectados }}</span>
          <span class="card-unidade">Und</span>
        </div>
      </div>

      <div class="col-6 col-lg-3">
        <div class="card card-ford h-100">
          <span class="card-label">Update Software</span>
          <span class="card-valor">{{ softwareAtualizado }}</span>
          <span class="card-unidade">Und</span>
        </div>
      </div>
    </div>

    <!-- Passo 10: imagem do veículo selecionado, ao centro da página -->
    <div class="vehicle-wrapper">
      <img
        *ngIf="selectedVehicle"
        [src]="selectedVehicle.img"
        [alt]="selectedVehicle.vehicle"
        class="vehicle-img"
      />
    </div>

    <!-- Passo 11: tabela com busca por código do veículo (VIN) -->
    <div class="tabela-ford">
      <table class="table table-bordered text-center align-middle mb-0">
        <thead>
          <tr>
            <th class="th-vin">Código - Vin</th>
            <th>Odômetro</th>
            <th>Nível de Combustível</th>
            <th>Status</th>
            <th>Lat.</th>
            <th>Long.</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td class="td-vin">
              <input
                type="text"
                class="form-control form-control-sm input-vin"
                placeholder="2FRHDUYS2Y63NHD22454"
                name="vin"
                [(ngModel)]="vin"
                (ngModelChange)="onVinChange($event)"
                (keyup.enter)="buscarVeiculo()"
              />
              <button type="button" class="btn btn-primary btn-sm btn-vin" (click)="buscarVeiculo()" aria-label="Buscar">
                <svg width="13" height="13" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
                  <path d="M11.74 10.34h-.68l-.24-.23a5.57 5.57 0 101.45-1.45l.23.24v.68l4.28 4.27-1.28 1.28-4.27-4.28zm-5.14 0a3.86 3.86 0 110-7.72 3.86 3.86 0 010 7.72z"/>
                </svg>
              </button>
            </td>
            <td>{{ vehicleData ? vehicleData.odometro + ' Km' : '—' }}</td>
            <td>{{ vehicleData ? vehicleData.nivelCombustivel + ' %' : '—' }}</td>
            <td>{{ vehicleData ? vehicleData.status : '—' }}</td>
            <td>{{ vehicleData ? vehicleData.lat : '—' }}</td>
            <td>{{ vehicleData ? vehicleData.long : '—' }}</td>
          </tr>
        </tbody>
      </table>

      <p class="aviso-vin" *ngIf="buscando">Buscando...</p>
      <p class="erro-vin" *ngIf="erroVin">{{ erroVin }}</p>
    </div>

    <!-- Códigos VIN cadastrados, sempre visíveis para seleção rápida -->
    <div class="vin-atalhos" *ngIf="vinOptions.length">
      <span class="vin-atalhos-label">Códigos cadastrados:</span>
      <button
        type="button"
        class="btn btn-outline-secondary btn-sm vin-chip"
        *ngFor="let codigo of vinOptions"
        [class.ativo]="codigo === vin"
        (click)="onVinSelecionado(codigo)"
      >
        {{ codigo }}
      </button>
    </div>
  </div>
</div>
